// Universal Message Sender - Robust version with error handling
const input = $input.item.json;

try {
  const channel = (input.channel || input.preferred_platform || 'telegram').toLowerCase();
  const recipient = input.recipient || input.chat_id || input.phone || input.sender_id;
  const message = input.message || input.text || input.body || input.input;
  const buttons = input.buttons || input.inline_keyboard || null;
  const mediaUrl = input.media_url || null;
  const customerId = input.customer_id || null;

  // Validate required fields
  if (!recipient || !message) {
    return {
      success: false,
      error: 'Missing recipient or message',
      channel: channel,
      skip_send: true
    };
  }

  return {
    channel: channel,
    recipient: String(recipient),
    message: String(message),
    buttons: buttons,
    mediaUrl: mediaUrl,
    customer_id: customerId,
    timestamp: new Date().toISOString(),
    skip_send: false
  };
} catch (err) {
  return {
    success: false,
    error: err.message,
    channel: 'unknown',
    skip_send: true
  };
}

// Log Telegram send - FREE, no cost
try {
  const normalized = $('Normalize Input').item.json;
  const result = $input.item.json;

  return {
    success: !result.error,
    channel: 'telegram',
    recipient: normalized.recipient,
    message_id: result.message_id || result.result?.message_id || null,
    customer_id: normalized.customer_id,
    cost_usd: 0.00,
    cost_type: 'free'
  };
} catch (err) {
  return {
    success: false,
    channel: 'telegram',
    error: err.message,
    cost_usd: 0.00
  };
}

// Calculate WhatsApp cost and log
try {
  const normalized = $('Normalize Input').item.json;
  const result = $input.item.json;

  return {
    success: !result.error,
    channel: 'whatsapp',
    recipient: normalized.recipient,
    message_id: result.messages?.[0]?.id || result.message_id || null,
    customer_id: normalized.customer_id,
    cost_usd: 0.005,
    cost_type: 'twilio_whatsapp'
  };
} catch (err) {
  return {
    success: false,
    channel: 'whatsapp',
    error: err.message,
    cost_usd: 0.005
  };
}

// Calculate SMS cost and log
try {
  const normalized = $('Normalize Input').item.json;
  const result = $input.item.json;
  const costUsd = result.price ? Math.abs(parseFloat(result.price)) : 0.0079;

  return {
    success: !result.error,
    channel: 'sms',
    recipient: normalized.recipient,
    message_id: result.sid || result.message_sid || null,
    customer_id: normalized.customer_id,
    cost_usd: costUsd,
    cost_type: 'twilio_sms'
  };
} catch (err) {
  return {
    success: false,
    channel: 'sms',
    error: err.message,
    cost_usd: 0.0079
  };
}

