  IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'log_api_usage') THEN
    PERFORM log_api_usage(
      $1::uuid, $2, $3, 'send_message', 0::int, 0::int, $4::decimal, 'SUB: Universal Messenger', 'Send Message', $5
    );
  END IF;
END $$;

