// Format successful response
const input = $input.item.json;
return {
  success: input.success !== false,
  channel: input.channel || 'unknown',
  recipient: input.recipient || input.chat_id || input.to || null,
  messageId: input.message_id || input.id || null,
  cost_tracked: (input.cost_usd || 0) > 0,
  timestamp: new Date().toISOString()
};

// Return error response for invalid input
return {
  success: false,
  error: $json.error || 'Invalid input',
  channel: $json.channel || 'unknown',
  timestamp: new Date().toISOString()
};
